create or replace function public.tamil_norm(t text)
returns text
language sql
immutable
parallel safe
as $$
  -- Generated by `cargo run -p tamil-norm --bin tamil-norm-sql`. Do not edit.
  select translate(
           regexp_replace(
             regexp_replace(lower(normalize(t, NFC)), '[^[:alnum:]\u0B80-\u0BFF]+', ' ', 'g'),
             '(?<=([\u0B85-\u0BB9a-z0-9][\u0BBE-\u0BCD]*){3,})(ினால்|ுடைய|ாலே|ிலே|க்கு|ால்|ில்|ின்|ோடு|ும்|ை)(?=\s|$)', '', 'g'),
           'ணநளழறஆஈஊஏஓஔீூேோௌா',
           'னனலலரஅஇஉஎஒஒிுெொொ')
$$;
